import { GeometryBase } from './Base/AbstractGeometryBase';
import { NLine } from './NLine';
import { NVector3 } from './NVector3';
// import { Point } from './Point';
export class NTriangle extends GeometryBase {
    p0: NVector3;
    p1: NVector3;
    p2: NVector3;
    cp: NVector3;
    public static GetLineFromTriangles(tris: NTriangle[]): NLine[] {
        let lns = [];
        for (let i = 0; i < tris.length; ++i) {
            let ls = tris[i].GetLine();
            for (let j = 0; j < ls.length; ++j) { lns.push(ls[j]); }
        }
        return lns;
    }
    public static GetLineFromTriangle(tri: NTriangle): NLine[] {
        return tri.GetLine();
    }
    constructor(p0: NVector3, p1: NVector3, p2: NVector3) {
        super();
        this.p0 = p0; this.p1 = p1; this.p2 = p2;
    }
    public GetCenter() {
        let x = (this.p0.x + this.p1.x + this.p2.x) / 3.0;
        let y = (this.p0.y + this.p1.y + this.p2.y) / 3.0;
        this.cp = new NVector3(x, y);
        return this.cp;
    }
    public GetLine(): NLine[] {
        return [new NLine(this.p0, this.p1), new NLine(this.p1, this.p2), new NLine(this.p2, this.p0)];
    }
    public GetLog(): string {
        throw new Error('Method not implemented.');
    }
    public RenderPost(ctx: CanvasRenderingContext2D): void {
        throw new Error('Method not implemented.');
    }
    public Render(ctx: CanvasRenderingContext2D): void {
        ctx.lineWidth = 0.5;
        ctx.strokeStyle = 'blue';
        ctx.fillStyle = 'rgba(255,0,0,0.5)';
        ctx.beginPath();
        ctx.moveTo(this.p0.x, this.p0.y);
        ctx.lineTo(this.p1.x, this.p1.y);
        ctx.lineTo(this.p2.x, this.p2.y);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
    }
    public IsMouseInside(x: number, y: number): boolean {
        if (NVector3.IsInsideOfVecs(new NVector3(x, y), [this.p0, this.p1, this.p2])) { return true; } else { return false; }
    }
    public Translate(x: number, y: number): void {
        throw new Error('Method not implemented.');
    }
    public Move(x: number, y: number): void {
        throw new Error('Method not implemented.');
    }
    public Remove(): void {
        throw new Error('Method not implemented.');
    }
    public Hide(): void {
        throw new Error('Method not implemented.');
    }
}